begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),
('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Knowledge brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('fact',public.create_brand_fact((select id from fixture where key='brand'),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','product','Test specification','Test source document','','Product team',current_date+30));
select is((select state from public.brand_facts),'pending','New facts are pending');
select is((select count(*)::int from public.brand_fact_revisions),1,'Creation records provenance');
select is(public.create_brand_fact((select id from fixture where key='brand'),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','product','Test specification','Test source document','','Product team',current_date+30),(select id from fixture where key='fact'),'Creation retry is idempotent');
select throws_ok($$select public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Claim','','','Team',current_date)$$,'23514',null,'Source is mandatory at database boundary');
select throws_ok($$select public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Claim','Source','javascript:alert(1)','Team',current_date)$$,'23514',null,'Unsafe source schemes rejected');
select throws_ok($$update public.brand_facts set state='approved'$$,'42501',null,'Direct approval denied');
select lives_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),1,'approved')$$,'Current fact can be explicitly approved');
select is((select version from public.brand_facts),2,'Approval creates a new immutable revision');
select is((select approved_by from public.brand_facts),auth.uid(),'Approval records verified actor');
select throws_ok($$select public.save_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),1,gen_random_uuid(),'product','Stale overwrite','Source','','Team',current_date+30)$$,'40001',null,'Stale correction cannot overwrite newer revision');
select lives_ok($$select public.save_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),2,gen_random_uuid(),'product','Corrected specification','Corrected source','','Team',current_date-1)$$,'Correction preserves history');
select is((select state from public.brand_facts),'pending','Correction resets approval');
select ok((select approved_by is null and approved_at is null from public.brand_facts),'Correction clears previous approval identity');
select throws_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),3,'approved')$$,'22023',null,'Overdue fact cannot be approved');
select is((select snapshot->>'statement' from public.brand_fact_revisions where version=1),'Test specification','Original statement remains in history');
select lives_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),3,'archived')$$,'Fact can be archived without deletion');
select is((select count(*)::int from public.brand_fact_revisions),4,'All content and review versions retained');
select throws_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),3,'approved')$$,'40001',null,'Stale approval cannot apply to another version');
insert into fixture values('invite',public.create_brand_invitation((select id from fixture where key='brand'),'other@example.invalid','operator',gen_random_uuid()));
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_facts),0,'Unrelated user cannot read facts');
select is((select count(*)::int from public.brand_fact_revisions),0,'Unrelated user cannot read history');
select throws_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),4,'approved')$$,'42501',null,'Unrelated user cannot approve');
insert into fixture values('agency',public.create_agency('Reader agency',gen_random_uuid()));
select public.accept_brand_invitation((select id from fixture where key='invite'),(select id from fixture where key='agency'));
select is((select count(*)::int from public.brand_facts),1,'Granted agency can read facts');
select is((select count(*)::int from public.brand_fact_revisions),4,'Granted agency can inspect provenance');
select throws_ok($$select public.review_brand_fact((select id from fixture where key='brand'),(select id from fixture where key='fact'),4,'approved')$$,'42501',null,'Operator grant does not permit fact approval');
select throws_ok($$select public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Claim','Source','','Team',current_date)$$,'42501',null,'Operator cannot create unreviewed brand facts');
reset role;
update public.organization_memberships set active=false where organization_id=(select id from fixture where key='agency');
set local role authenticated;
select is((select count(*)::int from public.brand_facts),0,'Revoked agency membership removes fact access');
insert into fixture values('otherbrand',public.create_owner_workspace('Other','Other brand','UTC','','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true));
select throws_ok($$select public.review_brand_fact((select id from fixture where key='otherbrand'),(select id from fixture where key='fact'),4,'archived')$$,'42501',null,'Cross-brand fact selector rejected');
reset role;
select throws_ok($$update public.brand_fact_revisions set snapshot='{}'$$,'42501',null,'Even privileged callers cannot rewrite history');
update public.brand_memberships set active=false where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select is((select count(*)::int from public.brand_facts),0,'Revocation removes fact reads');
select throws_ok($$select public.create_brand_fact((select id from fixture where key='brand'),gen_random_uuid(),'product','Claim','Source','','Team',current_date)$$,'42501',null,'Revocation blocks creation');
reset role;
set local role anon;
select throws_ok($$select * from public.brand_facts$$,'42501',null,'Anonymous facts denied');
reset role;
select * from finish();
rollback;
